--
-- Table structure for table `modules`
--

DROP TABLE IF EXISTS `modules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `modules` (
  `Id` char(36) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `GradeLevelId` char(36) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `Name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `CreatedByTeacherId` char(36) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  `IsActive` tinyint(1) NOT NULL DEFAULT '1',
  `CreatedAt` datetime(6) NOT NULL,
  `Credits` int NOT NULL DEFAULT '0',
  `Description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `PdfFileUrl` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `IsDeleted` tinyint(1) NOT NULL,
  `DeletedDate` datetime(6) DEFAULT NULL,
  `DeletedBy` char(36) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  `UpdatedDate` datetime(6) DEFAULT NULL,
  `UpdatedBy` char(36) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  `CreatedBy` char(36) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  `SubjectId` char(36) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  PRIMARY KEY (`Id`),
  UNIQUE KEY `IX_modules_GradeLevelId_Name` (`GradeLevelId`,`Name`),
  KEY `IX_modules_CreatedByTeacherId` (`CreatedByTeacherId`),
  KEY `IX_modules_grade_level` (`GradeLevelId`),
  KEY `IX_modules_IsDeleted` (`IsDeleted`),
  KEY `IX_modules_active` (`IsActive`),
  KEY `IX_modules_SubjectId` (`SubjectId`),
  CONSTRAINT `FK_modules_grade_levels_GradeLevelId` FOREIGN KEY (`GradeLevelId`) REFERENCES `grade_levels` (`Id`) ON DELETE RESTRICT,
  CONSTRAINT `FK_modules_subjects_SubjectId` FOREIGN KEY (`SubjectId`) REFERENCES `subjects` (`Id`) ON DELETE RESTRICT,
  CONSTRAINT `FK_modules_teachers_CreatedByTeacherId` FOREIGN KEY (`CreatedByTeacherId`) REFERENCES `teachers` (`Id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

